'use strict';
const BANK=window.QUESTION_BANK, ALL=Object.fromEntries(BANK.flatMap(c=>c.questions.map(q=>[q.id,q]))),KEY='robotics-study-v1';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageError=false,db={history:[],active:null},page='home',chapter='perception',mode='practice',count=10,result=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.history)){db=saved;if(db.active&&!validSession(db.active))db.active=null;db.history=db.history.filter(validSession);}}catch{storageError=true;}
function validSession(s){return s&&Array.isArray(s.items)&&s.items.length>0&&s.items.every(i=>ALL[i.id]&&Array.isArray(i.order)&&i.order.length===4&&new Set(i.order).size===4&&i.order.every(k=>'ABCD'.includes(k)))&&s.answers&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.items.length&&Number.isFinite(s.elapsed)&&['practice','exam'].includes(s.mode)&&BANK.some(c=>c.id===s.chapter);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{storageError=true;}}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function time(seconds){const s=Math.floor(seconds);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function chapterName(id){return BANK.find(c=>c.id===id)?.title||'';}
function score(s){const wrong=s.items.filter(i=>s.answers[i.id]!==ALL[i.id].correct).map(i=>i.id);return {wrong,correct:s.items.length-wrong.length,percent:Math.round((s.items.length-wrong.length)/s.items.length*100)};}
function studied(id){const set=new Set();db.history.filter(s=>s.chapter===id).forEach(s=>s.items.forEach(i=>{if(s.answers[i.id])set.add(i.id);}));if(db.active?.chapter===id)Object.keys(db.active.answers).forEach(k=>set.add(k));return set.size;}
function bilingual(en,vi,cls=''){return `<span class="en ${cls}" lang="en">${esc(en)}</span><span class="vi" lang="vi">${esc(vi)}</span>`;}
function render(){const active=page==='quiz';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">R</span><div>Robotics<span style="color:#d2f49a">.</span><small>STUDY LAB</small></div></div><nav><div class="nav-label">Góc học tập</div><button class="nav-btn ${page!=='history'?'active':''}" data-action="home"><span>▦</span><span>Luyện thi</span></button><button class="nav-btn ${page==='history'?'active':''}" data-action="history"><span>◷</span><span>Lịch sử học</span></button></nav><div class="side-note"><strong>English first. Vietnamese below.</strong>Học kiến thức robotics, làm quen với thuật ngữ tiếng Anh.</div></aside><main class="main"><header class="topbar"><span>AI & Robotics <span aria-hidden="true">/</span> ${active?'Đang làm bài':page==='result'?'Kết quả':page==='history'?'Lịch sử học':'Không gian luyện thi'}</span><span class="tag">EN <span aria-hidden="true">↕</span> VI · Song ngữ</span></header>${storageError?'<div class="alert" role="alert">Trình duyệt hiện không lưu được dữ liệu. Hãy cho phép lưu trữ để giữ lịch sử và bài đang làm.</div>':''}${page==='home'?home():page==='quiz'?quiz():page==='result'?results():history()}<footer class="footer"><span>ROBOTICS STUDY LAB</span><span>Tiến độ được lưu trên trình duyệt này</span></footer></main></div>`;}
function home(){const learned=BANK.reduce((n,c)=>n+studied(c.id),0),avg=db.history.length?Math.round(db.history.reduce((n,s)=>n+score(s).percent,0)/db.history.length):null;return `<div class="page-head"><div><div class="eyebrow">LEARN. PRACTICE. PROGRESS.</div><h1>Sẵn sàng cho bài thi tiếp theo.</h1><p>Chọn chương, thiết lập bài luyện và bắt đầu theo nhịp của bạn.</p></div></div>${db.active?`<div class="resume"><div><h3>Bạn có một bài đang làm</h3><p>${esc(chapterName(db.active.chapter))} · ${Object.keys(db.active.answers).length}/${db.active.items.length} câu đã chọn · ${db.active.mode==='practice'?'Practice':'Exam'}</p></div><button class="primary" data-action="resume">Tiếp tục bài làm →</button></div>`:''}<div class="metrics"><div class="metric"><div class="metric-icon">▤</div><div><b>200</b><span>Câu hỏi · 4 chương</span></div></div><div class="metric"><div class="metric-icon">✓</div><div><b>${learned}<small style="font-size:14px;color:#83907b;font-weight:400"> / 200</small></b><span>Câu đã luyện</span></div></div><div class="metric"><div class="metric-icon">↗</div><div><b>${avg===null?'—':avg+'%'}</b><span>Điểm trung bình · ${db.history.length} bài</span></div></div></div><div class="setup-layout"><section><div class="section-head"><h2>01 <span style="color:#a2ad9d">/</span> Chọn chương học</h2><span>50 câu mỗi chương</span></div><div class="chapters">${BANK.map((c,i)=>`<button class="chapter ${chapter===c.id?'selected':''}" data-chapter="${c.id}" aria-pressed="${chapter===c.id}"><div class="chapter-top"><span class="chapter-num">CHƯƠNG 0${i+1}</span><span class="radio" aria-hidden="true">${chapter===c.id?'✓':''}</span></div><h3 lang="en">${c.title}</h3><p>${['Nhận thức & điều khiển robot','Cảm biến & điều khiển chuyển động','Thị giác máy tính cho robot','Điều hướng tự hành'][i]}</p><div class="track"><i style="width:${studied(c.id)*2}%"></i></div><div class="chapter-footer"><span>${studied(c.id)}/50 câu đã luyện</span><span>${studied(c.id)*2}%</span></div></button>`).join('')}</div><div class="info-strip"><span style="font-size:20px">◎</span><div><b>Học đúng bộ câu hỏi của bạn.</b><br>Giữ nguyên nội dung và đáp án gốc. Câu hỏi và lựa chọn luôn hiển thị tiếng Anh trên, tiếng Việt dưới.</div></div></section><aside class="panel config"><h2>02 <span style="color:#a2ad9d">/</span> Thiết lập bài</h2><div><span class="field-label">Chế độ làm bài</span><div class="segments" role="group" aria-label="Chế độ">${['practice','exam'].map(m=>`<button data-mode="${m}" class="${mode===m?'chosen':''}" aria-pressed="${mode===m}">${m==='practice'?'Practice':'Exam'}</button>`).join('')}</div><p class="mode-help">${mode==='practice'?'Chọn đáp án để xem ngay đúng/sai và lời giải. Sau đó bấm Next để sang câu tiếp theo.':'Làm hết bài rồi nộp để chấm điểm. Đáp án và lời giải được giữ kín trong suốt bài thi.'}</p></div><div><span class="field-label">Số câu ngẫu nhiên</span><div class="segments" role="group" aria-label="Số câu">${[10,20,50].map(n=>`<button data-count="${n}" class="${n===count?'chosen':''}" aria-pressed="${n===count}">${n} câu</button>`).join('')}</div><p class="mode-help">↔ Trộn thứ tự câu hỏi và đáp án<br>◷ Có đồng hồ đếm thời gian</p></div><div><button class="primary" data-action="start">Bắt đầu làm bài <span>→</span></button><p class="subnote">${count} câu · ${mode==='practice'?'Luyện tập':'Thi thử'} · Tự động lưu</p></div></aside></div>`;}
function start(ids=null,source=null){const c=source?.chapter||chapter;const qs=ids||BANK.find(x=>x.id===c).questions.map(q=>q.id);db.active={id:crypto.randomUUID?.()||String(Date.now()),chapter:c,mode:source?.mode||mode,items:shuffle(qs).slice(0,ids?qs.length:count).map(id=>({id,order:shuffle(['A','B','C','D'])})),answers:{},checked:{},index:0,elapsed:0,retry:!!ids};page='quiz';save();render();window.scrollTo(0,0);}
function quiz(){const s=db.active;if(!s){page='home';return home();}const item=s.items[s.index],q=ALL[item.id],selected=s.answers[q.id],checked=s.mode==='practice'&&s.checked?.[q.id],answered=Object.keys(s.answers).length;return `<div class="page-head"><div><div class="eyebrow">${s.mode==='practice'?'PRACTICE · LUYỆN TẬP':'EXAM · THI THỬ'}${s.retry?' · ÔN CÂU SAI':''}</div><h1 style="font-size:26px">${esc(chapterName(s.chapter))}</h1></div></div><div class="quiz-top"><h2>Câu ${s.index+1}<span style="color:#84917e;font-size:16px;font-weight:400"> / ${s.items.length}</span></h2><div class="time" aria-label="Thời gian làm bài">◷ <span id="timer">${time(s.elapsed)}</span></div></div><div class="track" role="progressbar" aria-label="Số câu đã chọn" aria-valuenow="${answered}" aria-valuemin="0" aria-valuemax="${s.items.length}" style="margin-bottom:25px"><i style="width:${answered/s.items.length*100}%"></i></div><div class="quiz-layout"><section class="panel question"><div class="question-meta"><span>CHỌN MỘT ĐÁP ÁN</span><span>Câu gốc #${q.number}</span></div><h2 lang="en">${esc(q.en)}</h2><div class="vi">${esc(q.vi)}</div><div class="answers" role="group" aria-label="Các đáp án">${item.order.map((id,i)=>{const o=q.options.find(o=>o.id===id);return `<button class="answer ${selected===id?'selected':''} ${checked&&id===q.correct?'correct':''} ${checked&&selected===id&&id!==q.correct?'wrong':''}" data-answer="${id}" aria-pressed="${selected===id}" ${checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${bilingual(o.en,o.vi)}${checked&&id===q.correct?'<span class="badge">Đáp án đúng</span>':''}</span></button>`;}).join('')}</div>${checked?`<div class="feedback" role="status"><strong>${selected===q.correct?'✓ Chính xác!':'✕ Chưa chính xác. Đáp án đúng: '+ 'ABCD'[item.order.indexOf(q.correct)]}</strong><p>${esc(q.explanation||'Tài liệu gốc không cung cấp phần giải thích cho câu này.')}</p></div>`:`<p style="font-size:12px;margin-top:20px">${s.mode==='practice'?'Chọn đáp án để xem ngay kết quả và lời giải.':'Đáp án đúng chỉ hiển thị sau khi bạn nộp bài.'}</p>`}<div class="question-actions"><button class="secondary" data-action="previous" ${s.index===0?'disabled':''}>← Trước</button><button class="primary" data-action="next" ${!selected?'disabled':''}>${s.index===s.items.length-1?'Nộp bài':'Next →'}</button></div></section><aside class="panel navigator"><h3>Tiến độ bài làm</h3><p>${answered}/${s.items.length} câu đã chọn</p><div class="grid-questions">${s.items.map((it,i)=>`<button data-index="${i}" class="qdot ${s.answers[it.id]?'answered':''} ${i===s.index?'current':''}" aria-label="Câu ${i+1}${s.answers[it.id]?', đã chọn đáp án':''}" ${i===s.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p style="margin-top:20px">${s.mode==='practice'?'Đáp án được khóa sau khi chọn.':'Bạn có thể đổi đáp án trước khi nộp bài.'}</p><button class="secondary" data-action="home">Lưu & về trang đầu</button></aside></div>`;}
function finish(){const s=db.active;const missing=s.items.findIndex(i=>!s.answers[i.id]||(s.mode==='practice'&&!s.checked?.[i.id]));if(missing!==-1){s.index=missing;save();render();return;}s.completedAt=new Date().toISOString();db.history.unshift(structuredClone(s));result=db.history[0];db.active=null;page='result';save();render();window.scrollTo(0,0);}
function reviewQuestion(s,id){const q=ALL[id],item=s.items.find(i=>i.id===id),a=q.options.find(o=>o.id===s.answers[id]),correct=q.options.find(o=>o.id===q.correct);return `<details class="panel review"><summary><span style="color:#799168;font-size:12px">CÂU GỐC ${q.number}</span><br>${bilingual(q.en,q.vi)}</summary><div class="review-answer bad"><strong>Bạn chọn · ${'ABCD'[item.order.indexOf(a?.id)]||'—'}</strong>${a?bilingual(a.en,a.vi):'Chưa chọn'}</div><div class="review-answer"><strong>Đáp án đúng · ${'ABCD'[item.order.indexOf(q.correct)]}</strong>${bilingual(correct.en,correct.vi)}</div><div class="feedback"><strong>Giải thích từ tài liệu</strong><p>${esc(q.explanation||'Tài liệu gốc không cung cấp phần giải thích cho câu này.')}</p></div></details>`;}
function results(){if(!result){page='home';return home();}const r=score(result);return `<div class="page-head"><div><div class="eyebrow">SESSION COMPLETE</div><h1>Hoàn thành bài ${result.mode==='practice'?'luyện tập':'thi thử'}.</h1><p>${esc(chapterName(result.chapter))}</p></div></div><div class="score-banner"><div><h2>${r.percent>=80?'Bạn đang tiến bộ rất tốt.':r.percent>=50?'Tiếp tục củng cố kiến thức.':'Mỗi lần luyện là một bước tiến.'}</h2><p>${result.items.length} câu · ${time(result.elapsed)} · ${result.mode==='practice'?'Practice':'Exam'}</p></div><div class="score-number">${r.percent}%</div></div><div class="metrics"><div class="metric"><div><b>${r.correct}</b><span>Câu đúng</span></div></div><div class="metric"><div><b>${r.wrong.length}</b><span>Câu sai</span></div></div><div class="metric"><div><b>${time(result.elapsed)}</b><span>Thời gian làm bài</span></div></div></div><div class="result-actions">${r.wrong.length?'<button class="primary" data-action="retry">Làm lại '+r.wrong.length+' câu sai →</button>':''}<button class="secondary" data-action="home">Chọn bài mới</button><button class="secondary" data-action="history">Xem lịch sử</button></div><div class="section-head"><h2>Các câu cần ôn lại</h2><span>${r.wrong.length} câu</span></div>${r.wrong.length?r.wrong.map(id=>reviewQuestion(result,id)).join(''):'<div class="panel empty"><h3>Chính xác toàn bộ!</h3><p>Bạn đã trả lời đúng tất cả câu hỏi trong bài này.</p></div>'}`;}
function history(){return `<div class="page-head"><div><div class="eyebrow">YOUR LEARNING JOURNEY</div><h1>Lịch sử học tập.</h1><p>Xem lại kết quả và luyện riêng những câu còn sai.</p></div></div>${db.history.length?`<div class="history-list">${db.history.map((s,i)=>`<article class="panel history-row"><div><h3>${esc(chapterName(s.chapter))}</h3><p>${new Date(s.completedAt).toLocaleString('vi-VN')} · ${s.mode==='practice'?'Practice':'Exam'}${s.retry?' · Ôn câu sai':''}</p><p>${score(s).correct}/${s.items.length} câu đúng · ${time(s.elapsed)}</p></div><strong>${score(s).percent}%</strong><button class="secondary" data-result="${i}">Xem kết quả</button></article>`).join('')}</div>`:'<div class="panel empty"><h2>Hành trình của bạn bắt đầu từ đây.</h2><p>Hoàn thành bài luyện đầu tiên để lưu điểm và theo dõi tiến độ.</p><button class="primary" data-action="home">Chọn chương học →</button></div>'}`;}
function confirmReplace(action){if(!db.active){action();return;}const d=document.createElement('dialog');d.innerHTML='<h2>Bắt đầu bài mới?</h2><p>Bài đang làm sẽ được thay thế. Lịch sử các bài đã hoàn thành vẫn được giữ lại.</p><div class="dialog-actions"><button class="secondary" data-cancel>Giữ bài hiện tại</button><button class="primary" data-confirm>Bắt đầu bài mới</button></div>';document.body.append(d);d.showModal();d.querySelector('[data-cancel]').onclick=()=>{d.close();d.remove();};d.querySelector('[data-confirm]').onclick=()=>{d.close();d.remove();action();};d.oncancel=()=>d.remove();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.chapter){chapter=b.dataset.chapter;render();return;}if(b.dataset.mode){mode=b.dataset.mode;render();return;}if(b.dataset.count){count=+b.dataset.count;render();return;}if(b.dataset.result!==undefined){result=db.history[+b.dataset.result];page='result';render();return;}const s=db.active;if(b.dataset.answer&&page==='quiz'){if(s.checked?.[s.items[s.index].id])return;s.answers[s.items[s.index].id]=b.dataset.answer;if(s.mode==='practice'){s.checked??={};s.checked[s.items[s.index].id]=true;}save();render();return;}if(b.dataset.index!==undefined&&s){s.index=+b.dataset.index;save();render();return;}switch(b.dataset.action){case'home':page='home';break;case'history':page='history';break;case'start':confirmReplace(()=>start());return;case'resume':page='quiz';break;case'previous':s.index=Math.max(0,s.index-1);save();break;case'check':if(!s.answers[s.items[s.index].id])return;s.checked??={};s.checked[s.items[s.index].id]=true;save();break;case'next':if(!s.answers[s.items[s.index].id])return;if(s.index===s.items.length-1){finish();return;}s.index++;save();break;case'retry':confirmReplace(()=>start(score(result).wrong,result));return;default:return;}render();if(['next','previous','home','history'].includes(b.dataset.action))window.scrollTo(0,0);});
let last=Date.now();setInterval(()=>{const now=Date.now(),delta=(now-last)/1000;last=now;if(page==='quiz'&&db.active&&!document.hidden){db.active.elapsed+=delta;const t=$('#timer');if(t)t.textContent=time(db.active.elapsed);save();}},1000);
window.addEventListener('pagehide',save);
document.addEventListener('visibilitychange',()=>{last=Date.now();save();});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_study_progress',description:'Read chapter progress and completed quiz scores on this browser.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments expected');return {chapters:BANK.map(c=>({name:c.title,studied:studied(c.id),total:50})),completed:db.history.length,active:!!db.active};}})).catch(()=>{});}catch{}}
render();


